        @JavascriptInterface public void request(String id,String action,String payload){if(PhoneUiLaunch.dispatch(MainActivity.this,id,action,MainActivity.this::result))return;if(action.equals("samsungPickWgt")){runOnUiThread(()->{try{if(samsungWgtRequest!=null)throw new IOException("Finish the current file selection first.");samsungWgtRequest=id;Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(pick,33);}catch(Exception e){samsungWgtRequest=null;result(id,false,"Could not open the WGT picker.");}});return;}if(action.equals("dlnaPickFile")){runOnUiThread(()->{try{if(dlnaFileRequest!=null)throw new IOException("Finish the current file selection first.");dlnaFileRequest=id;Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"video/*","audio/*","image/*"}).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(pick,32);}catch(Exception e){dlnaFileRequest=null;result(id,false,"Could not open the system file picker.");}});return;}if(action.equals("openCastSettings")){runOnUiThread(()->{try{result(id,true,new JSONObject().put("opened",CastSettings.open(MainActivity.this)));}catch(Exception e){result(id,false,"Could not open Cast settings.");}});return;}if(action.equals("pickImage")){runOnUiThread(()->{try{if(imageRequest!=null)throw new IOException("اختار الصورة الحالية الأول.");String role=new JSONObject(payload).optString("role");if(!"art".equals(role))throw new IOException("Invalid image role");imageRequest=id;imageRole=role;Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(pick,31);}catch(Exception e){imageRequest=null;result(id,false,e.getMessage());}});return;}("faithPrayer".equals(action)?faithWorker:worker).execute(()->{try{result(id,true,run(action,new JSONObject(payload)));}catch(Exception e){result(id,false,e.getMessage()==null?"تعذّر تنفيذ الطلب.":e.getMessage());}});}
