    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode==7341){if(resultCode==RESULT_OK&&data!=null)showPhonePage(data.getStringExtra("page"));if(resultCode==RESULT_OK&&data!=null&&data.getBooleanExtra("classicKeyboard",false)&&web!=null)web.evaluateJavascript("if(window.MorphClassicRemote)MorphClassicRemote.open()",null);return;}if(requestCode==7340){faithOpening=false;if(resultCode==RESULT_OK&&data!=null&&web!=null){String page=data.getStringExtra("page");showPhonePage(page);}return;}if(requestCode==FaithVoicePacks.PICKER){if(resultCode!=RESULT_OK||data==null||data.getData()==null){runOnUiThread(()->web.evaluateJavascript("if(window.MorphWorship)MorphWorship.voicePackResult(false,true)",null));return;}final android.net.Uri voiceUri=data.getData();worker.execute(()->{boolean success=false;try(java.io.InputStream stream=getContentResolver().openInputStream(voiceUri)){if(stream==null)throw new IOException("No voice pack");FaithVoicePacks.install(this,stream);success=true;}catch(Exception ignored){}final boolean installed=success;runOnUiThread(()->{if(web!=null&&!isFinishing())web.evaluateJavascript("if(window.MorphWorship)MorphWorship.voicePackResult("+installed+",false)",null);});});return;}if(requestCode==33&&samsungWgtRequest!=null){final String id=samsungWgtRequest;samsungWgtRequest=null;if(resultCode!=RESULT_OK||data==null){result(id,true,new JSONObject());return;}final Uri uri=data.getData();worker.execute(()->{try{samsungWidget=SamsungWidget.read(getContentResolver().openInputStream(uri));result(id,true,samsungWidget.info());}catch(Exception e){samsungWidget=null;result(id,false,e.getMessage()==null?"Could not read this WGT file.":e.getMessage());}});return;}if(requestCode==32&&dlnaFileRequest!=null){final String id=dlnaFileRequest;dlnaFileRequest=null;if(resultCode!=RESULT_OK||data==null){result(id,true,new JSONObject());return;}final Uri uri=data.getData();worker.execute(()->{try{DlnaLocalFile file=new DlnaLocalFile(this,uri);dlnaFile=file;result(id,true,file.info());}catch(Exception e){result(id,false,e.getMessage()==null?"Could not read this file.":e.getMessage());}});return;}if(requestCode==31&&imageRequest!=null){final String id=imageRequest,role=imageRole;imageRequest=null;if(resultCode!=RESULT_OK||data==null){result(id,false,"تم إلغاء اختيار الصورة.");return;}final Uri uri=data.getData();worker.execute(()->{try{result(id,true,new JSONObject().put("role",role).put("data",ImageAsset.read(this,uri,role)));}catch(Exception e){result(id,false,"تعذّر قراءة الصورة. جرّب PNG أو JPEG أصغر.");}});}}
    @Override protected void onDestroy(){faithWorker.shutdownNow();synchronized(this){dlnaClosed=true;if(dlnaFileServer!=null)dlnaFileServer.close();}if(downloadServer!=null)downloadServer.close();if(samsungRemote!=null)samsungRemote.close();super.onDestroy();}
    @Override public void onBackPressed(){web.evaluateJavascript("(function(){var e=new Event('keydown',{bubbles:true,cancelable:true});Object.defineProperty(e,'keyCode',{value:27});Object.defineProperty(e,'key',{value:'Escape'});if(!document.dispatchEvent(e))return true;return window.handleBack?window.handleBack():false;})()",handled->{if("true".equals(handled)){exitBackAt=0;return;}if(!isFinishing()){long now=android.os.SystemClock.elapsedRealtime();if(exitBackAt!=0&&now-exitBackAt<=2000){exitBackAt=0;MainActivity.super.onBackPressed();}else exitBackAt=now;}});}
